declare module "*.module.scss" {
  const classes: Record<string, string>;
  export default classes;
}

declare module "*.css" {
  const css: string;
  export default css;
}

declare module "*.svg" {
  const src: string;
  export default src;
}

declare module "*.gif" {
  const src: string;
  export default src;
}

declare module "*.png" {
  const src: string;
  export default src;
}

declare module "*.scss" {
  const scss: string;
  export default scss;
}
